const test = require('node:test')
const assert = require('node:assert/strict')

// Import selected source modules only
const { orderBoxes } = require('../src/localBrain/examples/stock.js')
const { formatDuration, formatClockDuration } = require('../src/localBrain/examples/duration.js')

// Test 1: Preserves existing exact-decimal orderBoxes examples and validation assertions
// Includes at least one executable assert comparison containing a direct selected-relative require call.
test('orderBoxes preserves exact-decimal examples and validation from read-only source', () => {
  // Exact decimal quantity examples from criteria
  assert.equal(orderBoxes(3, 10, 4), 2)
  assert.equal(orderBoxes(0.1, 0.4, 0.1), 3)
  assert.equal(orderBoxes(0, 1.1, 0.1), 11)
  assert.equal(orderBoxes(1.01, 1.04, 0.01), 3)
  assert.equal(orderBoxes(12, 10, 4), 0)

  // Validation assertions for invalid inputs
  const invalidInputs = [NaN, Infinity, -Infinity, '2', undefined, null, true, {}, []]
  for (const v of invalidInputs) {
    for (let i = 0; i < 3; i++) {
      const args = [1, 3, 1]
      args[i] = v
      assert.throws(() => orderBoxes(...args), RangeError)
    }
  }

  // Edge cases with MIN_VALUE and MAX_SAFE_INTEGER
  assert.equal(orderBoxes(0, Number.MIN_VALUE, Number.MIN_VALUE), 1)
  assert.equal(orderBoxes(0, Number.MAX_SAFE_INTEGER, 1), Number.MAX_SAFE_INTEGER)
  assert.throws(() => orderBoxes(0, Number.MAX_VALUE, Number.MIN_VALUE), RangeError)
})

// Test 2: Preserves every existing formatDuration valid and invalid assertion including MAX_SAFE_INTEGER
test('formatDuration preserves safe-integer input validation and exact remainder values', () => {
  // Valid assertions from read-only source
  for (const s of [0, 59, 60, 119, 120, 3600, Number.MAX_SAFE_INTEGER]) {
    const n = BigInt(s)
    assert.equal(formatDuration(s), (n / 60n) + 'm ' + (n % 60n) + 's')
  }

  // Invalid assertions from read-only source
  for (const s of [Number.MAX_SAFE_INTEGER + 1, -1, 1.5, NaN, Infinity, '60', null, undefined, {}, 60n]) {
    assert.throws(() => formatDuration(s), RangeError)
  }
})

// Test 3: Exercises the new exported formatClockDuration with exact expected values and rejections
test('formatClockDuration exercises new behavior with exact expected values and rejections', () => {
  // Valid assertions with exact expected values from criteria
  assert.equal(formatClockDuration(0), '00:00:00')
  assert.equal(formatClockDuration(9), '00:00:09')
  assert.equal(formatClockDuration(59), '00:00:59')
  assert.equal(formatClockDuration(60), '00:01:00')
  assert.equal(formatClockDuration(3599), '00:59:59')
  assert.equal(formatClockDuration(3600), '01:00:00')
  assert.equal(formatClockDuration(86399), '23:59:59')
  assert.equal(formatClockDuration(86400), '24:00:00')
  assert.equal(formatClockDuration(360000), '100:00:00')
  assert.equal(formatClockDuration(Number.MAX_SAFE_INTEGER), '2501999792983:36:31')

  // Invalid assertions with RangeError for every other input type
  const invalidInputs = [-1, 1.5, NaN, Infinity, -Infinity, Number.MAX_SAFE_INTEGER + 1, '0', null, undefined, true, false, {}, [], BigInt(0)]
  for (const v of invalidInputs) {
    assert.throws(() => formatClockDuration(v), RangeError)
  }
})",
